// Implementation outline
function maxScorePartition(s, k) {
  const n = s.length;
  const dist = Array.from({length:n}, ()=>Array(n).fill(0));
  for (let l=0;l<n;l++) {
    const seen = new Set();
    for (let r=l;r<n;r++) { seen.add(s[r]); dist[l][r] = seen.size; }
  }
  const dp = Array.from({length:n+1}, ()=>Array(k+1).fill(-Infinity));
  const par = Array.from({length:n+1}, ()=>Array(k+1).fill(-1));
  for (let i=1;i<=n;i++) dp[i][1] = dist[0][i-1];
  for (let t=2;t<=k;t++){
    for (let i=t;i<=n;i++){
      for (let j=t-1;j<i;j++){
        const v = dp[j][t-1] + dist[j][i-1];
        if (v > dp[i][t]) { dp[i][t] = v; par[i][t] = j; }
      }
    }
  }
  // reconstruction omitted
  return {dp, par};
}
```

## Why This Is Asked
This problem extends the classic Longest Palindromic Subsequence (LPS) problem by allowing up to k character deletions, requiring a 3D DP formulation. It tests understanding of subsequence DP with additional constraints, careful boundary handling, and the ability to reconstruct the solution path.

## Key Concepts
- Longest Palindromic Subsequence with deletions
- 3D DP (i, j, d) where d represents remaining deletions
- Path reconstruction for deletion decisions
- Time/space complexity: O(n²·k) time, O(n²·k) space

## Code Example
```javascript
function longestPalindromicSubseqWithDeletions(s, k) {
  const n = s.length;
  const dp = Array.from({ length: n }, () =>
    Array.from({ length: n }, () => Array(k + 1).fill(0))
  );

  for (let i = 0; i < n; i++) {
    for (let d = 0; d <= k; d++) {
      dp[i][i][d] = 1;
    }
  }

  for (let len = 2; len <= n; len++) {
    for (let i = 0; i + len <= n; i++) {
      const j = i + len - 1;
      for (let d = 0; d <= k; d++) {
        if (s[i] === s[j]) {
          dp[i][j][d] = Math.max(dp[i][j][d], (len > 2 ? dp[i + 1][j - 1][d] : 0) + 2);
        }
        if (d > 0) {
          dp[i][j][d] = Math.max(dp[i][j][d], dp[i + 1][j][d - 1], dp[i][j - 1][d - 1]);
        }
      }
    }
  }

  return dp[0][n - 1][k];
}
```

## Why This Is Asked
Explores a DP variant transforming flips into max-sum of k disjoint subarrays on a simple gain array.

## Key Concepts
- DP with two matrices: dp for best total, best for segments ending at i
- Transform 0/1 to +1/-1 gains to linearize gains
- Reconstructing segments via parent pointers

## Code Example
```javascript
function maxOnesAfterKFlips(s, k) {
  const n = s.length;
  const gain = Array.from({length:n}, (_,i)=> s[i]==='0'?1:-1);
  const NEG = -1e9;
  const dp = Array.from({length:n+1},()=>Array(k+1).fill(NEG));
  const best = Array.from({length:n+1},()=>Array(k+1).fill(NEG));
  dp[0][0]=0;
  for(let i=1;i<=n;i++){
    for(let t=0;t<=k;t++){
      best[i][t] = Math.max(best[i-1][t] + gain[i-1], dp[i-1][t-1] + gain[i-1]);
      dp[i][t] = Math.max(dp[i-1][t], best[i][t]);
    }
  }
  const ones = s.split('').filter(c=>c==='1').length;
  return ones + dp[n][k];
}
```

## Why This Is Asked
This introduces selecting non-covering, fixed-cost segments, a natural DP with a running max optimization. It tests understanding of prefix sums, state pruning, and reconstruction.

## Key Concepts
- Prefix sums to compute segment sums in O(1)
- DP over i and t with exactly t segments
- Running maximum best[t] to avoid O(n) inner loop
- Path reconstruction to recover endpoints

## Code Example
```javascript
function maxValueSegments(A, k, c){
  const n = A.length;
  const S = Array(n+1).fill(0);
  for(let i=1;i<=n;i++) S[i]=S[i-1]+A[i-1];
  const negInf = -1e18;
  const dp = Array.from({length:n+1},()=>Array(k+1).fill(negInf));
  const par = Array.from({length:n+1},()=>Array(k+1).fill([-1,-1]));
  dp[0][0]=0;
  for(let t=1;t<=k;t++) par[0][t]=[-1,-1];
  for(let t=1;t<=k;t++){
    let best = negInf; // max of dp[m][t-1]-S[m]
    for(let i=1;i<=n;i++){
      best = Math.max(best, dp[i-1][t-1]-S[i-1]);
      const val = best + S[i] - c;
      if(val > dp[i][t]){ dp[i][t]=val; par[i][t]=[i-1,-1]; }
      if(dp[i-1][t] > dp[i][t]){ dp[i][t]=dp[i-1][t]; par[i][t]=[i-1,t]; }
    }
  }
  // reconstruction (simple version)
  let i=n, t=k, ends=[];
  while(t>0){
    const [pi, pt] = par[i][t] || [-1,-1];
    if(pi===-1) break;
    // approximate end at i, start at some m where dp[m][t-1]-S[m] was max
    // for brevity here, return only values; full reconstruction can be added as needed
    ends.push(i);
    i = pi; t--;
  }
  return { value: dp[n][k], ends: ends.reverse() };
}
```

